require_once '../../config/database.php'; require_once '../../config/helpers.php'; require_role('admin');
$q=trim($_GET['q']??''); $like='%'.$q.'%';
$stmt=mysqli_prepare($conn,"SELECT id,student_no,full_name,username FROM users WHERE role='student' AND (full_name LIKE ? OR student_no LIKE ? OR username LIKE ?) ORDER BY id DESC");
mysqli_stmt_bind_param($stmt,'sss',$like,$like,$like);mysqli_stmt_execute($stmt);$result=mysqli_stmt_get_result($stmt);
?>
